import{_ as d,o as t,c as a,ag as o}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"复数信号源","description":"","frontmatter":{},"headers":[],"relativePath":"v0.3.0-alpha/modules/complex_signal_source/index.md","filePath":"v0.3.0-alpha/modules/complex_signal_source/index.md"}'),c={name:"v0.3.0-alpha/modules/complex_signal_source/index.md"};function r(l,e,i,n,h,s){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="复数信号源" tabindex="-1">复数信号源 <a class="header-anchor" href="#复数信号源" aria-label="Permalink to &quot;复数信号源&quot;">​</a></h1><p>适用：v0.3.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>complex_signal_source</code> · 模块定义版本：6</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>生成包含实部 I 与虚部 Q 的复数信号。复数正弦、余弦可表示旋转相量，适合观察相位、正负频率和复数混频。I 与 Q 是同一时刻的两个坐标。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>复数信号源.out → 复数增益器.in</code>，也可直接绑定观察器并切换 I/Q 或星座显示。要观察两个实数分量，可接 I/Q 分解器；<code>cmd</code> 为独立消息输入。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>cmd</code>（cmd（消息））</td><td><code>message</code></td><td>消息；不计入流路数</td></tr><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>采样率决定相量每秒更新多少次，频率决定每次转过的角度。<code>frequency_hz</code> 须满足半开范围 <code>[-Fs/2, Fs/2)</code>，其中 <code>Fs</code> 为 <code>sample_rate_hz</code>：包含负边界，不含正边界。正负频率对应相反的旋转方向；观察复数双边频谱时应保留这个区别。</p><p>幅度缩放相量，初相改变起始方向，复数偏置移动整个轨迹的中心。原生复数正弦／余弦都产生旋转相量，其他波形的 I/Q 仍按各自定义生成，不能只看名称推断轨迹。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>采样率 (Hz)<br><code>sample_rate_hz</code></td><td><code>4096</code></td><td>范围 1 至 1000000；Master 支持 1–1000000 Hz，可输入小数；下限保证单个采样周期不超过 1 秒。</td><td>重新准备</td></tr><tr><td>频率 (Hz)<br><code>frequency_hz</code></td><td><code>64</code></td><td>范围 -500000 至 500000；必须小于采样率的一半；严格小于 <code>sample_rate_hz</code> × 0.5；还须满足本节关联约束</td><td>可在线应用</td></tr><tr><td>幅度<br><code>amplitude</code></td><td><code>1</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>波形<br><code>waveform</code></td><td><code>cosine</code></td><td>正弦 (<code>sine</code>)；余弦 (<code>cosine</code>)；方波 (<code>square</code>)；三角波 (<code>triangle</code>)；锯齿波 (<code>sawtooth</code>)；常量 (<code>constant</code>)；原生复数正弦与余弦均产生旋转相量，其他波形保留原生 I/Q 分量。</td><td>可在线应用</td></tr><tr><td>初相 (rad)<br><code>phase_rad</code></td><td><code>0</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>偏置实部<br><code>offset_real</code></td><td><code>0</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>偏置虚部<br><code>offset_imag</code></td><td><code>0</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>frequency_hz</code></li><li><code>amplitude</code></li><li><code>waveform</code></li><li><code>phase_rad</code></li><li><code>offset_real</code>、<code>offset_imag</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>复数偏置的实部与虚部作为一组应用。采样率变化需要重新准备。消息字典中的 <code>offset</code> 是当前消息接口支持的实数值，不能把它当作任意复数偏置；需要分别设置 I/Q 偏置时使用模块参数。</p><p>当前属性页未提供消息投递表单，消息步骤由配套开发验证脚本调用运行控制接口执行。打开工程后普通 F5 运行的是工程中的初始图，不会恢复上次投递的消息。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="复数处理与-i-q-往返" tabindex="-1">复数处理与 I/Q 往返 <a class="header-anchor" href="#复数处理与-i-q-往返" aria-label="Permalink to &quot;复数处理与 I/Q 往返&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/complex-iq.cnsproj" download>下载 complex-iq.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 2048 item，工程不保存样本。</p><p>复数处理与 I/Q 往返</p><ul><li>观察复数旋转相量、乘 j 的相位变化及 I/Q 分解再合成；复数频谱保留正负频率。</li></ul><h3 id="_512-点周期-hamming-与-75-重叠频谱" tabindex="-1">512 点周期 Hamming 与 75% 重叠频谱 <a class="header-anchor" href="#_512-点周期-hamming-与-75-重叠频谱" aria-label="Permalink to &quot;512 点周期 Hamming 与 75% 重叠频谱&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/spectrum-configuration.cnsproj" download>下载 spectrum-configuration.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 2048 item，工程不保存样本。</p><p>512 点周期 Hamming 与 75% 重叠频谱</p><ul><li>两路同为 4096 item/s，FFT 长度 512，周期 Hamming，重叠 75%（步长 128）。有限 2048 item 各产生 13 帧；实数单边谱在 256 Hz 峰值 1.25，复数双边谱在 -512 Hz 峰值 0.625。</li></ul><p>复数处理示例生成两个不同频率的相量。观察复数信号源 1 的 I/Q 波形和星座轨迹，再查看与其相连的复数增益器如何旋转相量。频谱应按实际正负频率解释，全部为本机仿真。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>星座显示为什么是圆而不是几个点？</strong> 连续相量不断改变相位，离散星座点通常来自符号映射器。</p><p><strong>只有 I 波形看着像实数正弦？</strong> 同时观察 Q 和复数频谱，单看一个分量会丢失旋转方向信息。</p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/07-iq/">07 用两个坐标认识 I/Q</a></li></ul>',36)])])}const u=d(c,[["render",r]]);export{m as __pageData,u as default};
